if doc.appraisal:
    appraisal = frappe.get_doc("Appraisal", doc.appraisal)

    # Do not change a submitted Appraisal. New flow keeps Appraisal in Draft until feedback is submitted.
    if appraisal.docstatus == 0:
        feedback_scores = frappe.get_all(
            "Employee Performance Feedback",
            filters={"appraisal": appraisal.name, "docstatus": 1},
            pluck="total_score",
        )

        # Calculate feedback average here so the result does not depend on hook execution order.
        if feedback_scores:
            feedback_score = sum(float(score or 0) for score in feedback_scores) / len(feedback_scores)
        else:
            feedback_score = 0

        # Real Group final score rule: feedback score is mandatory.
        goal_score = float(appraisal.total_score or 0)
        self_score = float(appraisal.self_score or 0)

        if feedback_score <= 0:
            final_score = 0
        elif goal_score > 0 and self_score > 0:
            final_score = int(((goal_score + feedback_score + self_score) / 3) + 0.5)
        elif goal_score > 0:
            final_score = int(((goal_score + feedback_score) / 2) + 0.5)
        elif self_score > 0:
            final_score = int(((feedback_score + self_score) / 2) + 0.5)
        else:
            final_score = int(feedback_score + 0.5)

        frappe.db.set_value(
            "Appraisal",
            appraisal.name,
            {"avg_feedback_score": feedback_score, "final_score": final_score},
        )

