def seconds_to_hhmm(total_seconds):
    if total_seconds is None:
        return "00:00"
    try:
        total_seconds = int(round(float(total_seconds)))
    except Exception:
        return "00:00"

    if total_seconds < 0:
        total_seconds = 0

    hours = total_seconds // 3600
    minutes = (total_seconds % 3600) // 60

    hours_text = ("0" + str(hours)) if hours < 10 else str(hours)
    minutes_text = ("0" + str(minutes)) if minutes < 10 else str(minutes)
    return hours_text + ":" + minutes_text


