def get_selected_period():
    today = frappe.utils.getdate(frappe.utils.today())
    selected_year = str(today.year)
    selected_month = month_map.get(str(today.month).zfill(2))

    if f_year and f_year != "null":
        selected_year = str(f_year)
    if f_month and f_month != "null":
