    month_int = None
    for key in month_map:
        if month_map.get(key) == selected_month:
            month_int = key
            break
    if not month_int:
        month_int = str(today.month).zfill(2)

    month_start = frappe.utils.getdate(selected_year + "-" + month_int + "-01")
    month_end = frappe.utils.getdate(frappe.utils.get_last_day(month_start))
    display_end = month_end
    if display_end > today:
        display_end = today

    target_dates = []
    current_date = month_start
    while current_date <= display_end:
        target_dates.append(current_date)
        current_date = frappe.utils.add_days(current_date, 1)

    return {"month_start": month_start, "month_end": month_end, "target_dates": target_dates}


