def get_work_seconds(logs):
    total_seconds = 0
    open_in = None

    for log_row in logs:
        log_type = (log_row.get("log_type") or "").upper()
        event_time = get_processed_datetime(log_row)
        if not event_time:
            continue

        if log_type == "IN":
            open_in = event_time
        elif log_type == "OUT":
            if open_in and event_time >= open_in:
                total_seconds += int((event_time - open_in).total_seconds())
                open_in = None

    return total_seconds


