def build_live_status(holiday_tag, leave_row, request_row, valid_pair, has_any_logs):
    leave_type = None
    leave_half = 0
    if leave_row:
        leave_type = leave_row.get("leave_type")
        leave_half = 1 if leave_row.get("half_day") else 0

    request_reason = ""
    request_half = 0
    request_was_half = 0
    if request_row:
        request_reason = (request_row.get("reason") or "").strip()
        request_half = 1 if request_row.get("half_day") else 0
        request_was_half = 1 if request_row.get("custom_was_half_day") else 0

    if holiday_tag and valid_pair:
        if holiday_tag == "WO":
            return "POW"
        return "POH"

    if holiday_tag and not has_any_logs and not leave_type and not request_reason:
        return holiday_tag

    leave_abbr = get_leave_abbr(leave_type)
    reason_upper = request_reason.upper()

    if reason_upper in ("OFFICIAL", "TOUR"):
        if leave_abbr:
            return "OD" + leave_abbr
        if valid_pair:
            return "POD"
        if request_half or request_was_half:
            return "HOD"
        return "OD"

    if leave_abbr:
        if valid_pair and (leave_half or request_half or request_was_half):
            return "H" + leave_abbr
        if valid_pair:
            return "P" + leave_abbr
        return leave_abbr

    if reason_upper == "MIS PUNCH":
        return "MIS"

    if holiday_tag and not has_any_logs:
        return holiday_tag

    if valid_pair:
        return "P"
    if has_any_logs:
        return "MIS"
    return "A"


