        return custom_tag

    status = (attendance_row.get("status") or "").strip()
    leave_type = attendance_row.get("leave_type")
    if not leave_type and leave_row:
        leave_type = leave_row.get("leave_type")

    request_reason = ""
    request_half = 0
    request_was_half = 0
    if request_row:
        request_reason = (request_row.get("reason") or "").strip()
        request_half = 1 if request_row.get("half_day") else 0
        request_was_half = 1 if request_row.get("custom_was_half_day") else 0

    leave_abbr = get_leave_abbr(leave_type)
    reason_upper = request_reason.upper()

    if reason_upper in ("OFFICIAL", "TOUR"):
        if leave_abbr:
            return "OD" + leave_abbr
        if status == "Present":
            return "POD"
        if status == "Half Day" or request_half or request_was_half:
            return "HOD"
        return "OD"

    if leave_abbr:
        if status == "Present":
            return "P" + leave_abbr
        if status == "Half Day" or request_half or request_was_half:
            return "H" + leave_abbr
        return leave_abbr

    return normalize_tag(status) or "A"


def build_attendance_row(target_date, attendance_row, leave_row, request_row, logs):
    status = get_final_status(attendance_row, leave_row, request_row)
    late_in = "00:00"
    early_exit = "00:00"

    sorted_logs = sorted(logs, key=lambda row: row.get("time") or row.get("shift_start") or row.get("shift_end"))
    first_in_log = get_first_log(sorted_logs, "IN")
    last_out_log = get_last_log(sorted_logs, "OUT")
    first_in_dt = get_processed_datetime(first_in_log) if first_in_log else None
    last_out_dt = get_processed_datetime(last_out_log) if last_out_log else None

    if first_in_log and first_in_log.get("shift_start") and first_in_dt:
        shift_start_dt = frappe.utils.get_datetime(first_in_log.get("shift_start"))
        late_seconds = int((first_in_dt - shift_start_dt).total_seconds())
        if late_seconds > 0:
            late_in = seconds_to_hhmm(late_seconds)

    if last_out_log and last_out_log.get("shift_end") and last_out_dt:
        shift_end_dt = frappe.utils.get_datetime(last_out_log.get("shift_end"))
        early_seconds = int((shift_end_dt - last_out_dt).total_seconds())
        if early_seconds > 0:
            early_exit = seconds_to_hhmm(early_seconds)

    return {
        "status": status,
        "status_color": get_status_color(status),
        "attendance_date": frappe.utils.format_date(target_date),
        "day": frappe.utils.get_weekday(target_date)[:3].upper(),
        "in": "IN: " + format_hhmm(attendance_row.get("in_time")),
        "late_in": late_in,
        "out": "OUT: " + format_hhmm(attendance_row.get("out_time")),
        "early_exit": "" if early_exit == "00:00" else early_exit,
        "shift": str(attendance_row.get("shift") or "N/A") + " | " + seconds_to_hhmm((attendance_row.get("working_hours") or 0) * 3600),
        "has_variation": get_variation(sorted_logs),
    }


def build_live_row(target_date, logs, holiday_tag, leave_row, request_row):
    logs = sorted(logs, key=lambda row: row.get("time") or row.get("shift_start") or row.get("shift_end"))

    first_in_log = get_first_log(logs, "IN")
    last_out_log = get_last_log(logs, "OUT")

    first_in_dt = get_processed_datetime(first_in_log) if first_in_log else None
    last_out_dt = get_processed_datetime(last_out_log) if last_out_log else None

    valid_pair = 1 if (first_in_dt and last_out_dt and last_out_dt >= first_in_dt) else 0
    has_any_logs = 1 if len(logs) > 0 else 0

    late_in = "00:00"
    if first_in_log and first_in_log.get("shift_start") and first_in_dt:
        shift_start_dt = frappe.utils.get_datetime(first_in_log.get("shift_start"))
        late_seconds = int((first_in_dt - shift_start_dt).total_seconds())
        if late_seconds > 0:
            late_in = seconds_to_hhmm(late_seconds)

    early_exit = "00:00"
    if last_out_log and last_out_log.get("shift_end") and last_out_dt:
        shift_end_dt = frappe.utils.get_datetime(last_out_log.get("shift_end"))
        early_seconds = int((shift_end_dt - last_out_dt).total_seconds())
        if early_seconds > 0:
            early_exit = seconds_to_hhmm(early_seconds)

    shift_name = "N/A"
    for log_row in logs:
        if log_row.get("shift"):
            shift_name = log_row.get("shift")
            break

    work_seconds = get_work_seconds(logs)
    status = build_live_status(holiday_tag, leave_row, request_row, valid_pair, has_any_logs)

    return {
        "status": status,
        "status_color": get_status_color(status),
        "attendance_date": frappe.utils.format_date(target_date),
        "day": frappe.utils.get_weekday(target_date)[:3].upper(),
        "in": "IN: " + (format_hhmm(first_in_dt) if first_in_dt else "N/A"),
        "late_in": late_in,
        "out": "OUT: " + (format_hhmm(last_out_dt) if last_out_dt else "N/A"),
        "early_exit": "" if early_exit == "00:00" else early_exit,
        "shift": str(shift_name or "N/A") + " | " + seconds_to_hhmm(work_seconds),
        "has_variation": get_variation(logs),
    }


employee = resolve_employee()
if not employee:
    frappe.response["message"] = []
else:
    period = get_selected_period()
    month_start = period.get("month_start")
    month_end = period.get("month_end")
    target_dates = period.get("target_dates") or []
    holiday_list = frappe.db.get_value("Employee", employee, "holiday_list")
    holiday_map = build_holiday_map(holiday_list, month_start, month_end)

    attendance_rows = frappe.get_all(
        "Attendance",
        filters={
            "employee": employee,
            "attendance_date": ["between", [month_start, month_end]],
            "docstatus": 1,
        },
        fields=[
            "name", "attendance_date", "status", "custom_attendance_tag", "shift",
            "in_time", "out_time", "working_hours", "late_entry", "early_exit",
            "leave_type", "leave_application", "attendance_request", "modified",
        ],
        order_by="attendance_date desc, modified desc",
    )

    attendance_by_date = {}
    for row in attendance_rows:
        key = str(row.get("attendance_date"))
        if key not in attendance_by_date:
            attendance_by_date[key] = row

    leave_rows = frappe.get_all(
        "Leave Application",
        filters={
            "employee": employee,
            "docstatus": 1,
            "from_date": ["<=", month_end],
            "to_date": [">=", month_start],
        },
        fields=[
            "name", "from_date", "to_date", "leave_type", "half_day",
            "half_day_date", "custom_half_type",
        ],
        order_by="modified desc",
    )

    request_rows = frappe.get_all(
        "Attendance Request",
        filters={
            "employee": employee,
            "docstatus": 1,
            "from_date": ["<=", month_end],
            "to_date": [">=", month_start],
        },
        fields=[
            "name", "from_date", "to_date", "reason", "half_day",
        ],
        order_by="modified desc",
    )

    checkin_end = frappe.utils.add_days(month_end, 1)
    checkin_rows = frappe.get_all(
        "Employee Checkin",
        filters={
            "employee": employee,
            "time": ["between", [
                str(month_start) + " 00:00:00",
                str(checkin_end) + " 23:59:59",
            ]],
        },
        fields=[
            "name", "time", "log_type", "shift", "shift_start", "shift_end",
            "attendance", "skip_auto_attendance", "custom_processed_time", "custom_area",
        ],
        order_by="time asc",
    )

    checkins_by_date = {}
    for log_row in checkin_rows:
        target_date = get_checkin_attendance_date(log_row)
        if not target_date:
            continue
        if target_date < month_start or target_date > month_end:
            continue

        key = str(target_date)
        if key not in checkins_by_date:
            checkins_by_date[key] = []
        checkins_by_date[key].append(log_row)

    response_rows = []
    target_dates = sorted(target_dates, reverse=True)
    for target_date in target_dates:
        key = str(target_date)
        attendance_row = attendance_by_date.get(key)
        leave_row = get_matching_row(leave_rows, target_date)
        request_row = get_matching_row(request_rows, target_date)
        holiday_tag = holiday_map.get(key)

        if attendance_row:
            logs = checkins_by_date.get(key) or []
            response_rows.append(build_attendance_row(target_date, attendance_row, leave_row, request_row, logs))
        else:
            logs = checkins_by_date.get(key) or []
            response_rows.append(build_live_row(target_date, logs, holiday_tag, leave_row, request_row))

    frappe.response["message"] = response_rows
